INSERT OR IGNORE INTO "site_setting" ("id", "siteTitle", "ownerName", "heroGreeting", "heroRoles", "heroTagline", "avatarUrl", "aboutTitle", "aboutText", "resumeUrl", "email", "phone", "location", "availability", "primaryColor", "accentColor", "marqueeText", "footerText", "updatedAt") VALUES ('main', 'MD Salahuddin — Creative Full-Stack Developer', 'MD Salahuddin', 'Hello, I''m', 'Full-Stack Developer, Next.js Specialist, UI Architecture Lead, Open-Source Contributor', 'I craft immersive, high-performance digital products where engineering precision meets editorial design. Every interaction is tuned for sub-second speed and visual clarity.', '/images/avatar.svg', 'Crafting digital *excellence* since day one', 'I''m a full-stack engineer and interaction designer who believes great software should feel instantaneous and alive. For over 5 years I''ve architected and shipped web applications for startups and global agencies — from high-converting product launches to real-time data platforms.

My focus lives at the intersection of systems engineering and tactile interfaces: **Next.js App Router**, **TypeScript**, **SQLite WAL**, and **60fps motion choreography**. When I''m not shipping production code, you''ll find me auditing web performance, refining design systems, or contributing to open-source developer tools.', '#contact', 'hello@mdsalahuddin.dev', '+880 1700 000000', 'Dhaka, Bangladesh', 'Available for select projects', '#8b5cf6', '#d946ef', 'Full-Stack Engineering, Next.js 15 SSR, UI/UX Architecture, High-FPS Motion, TypeScript Systems, SQLite & Edge APIs, Web Performance, Design Systems', 'Engineered for speed & visual precision', '2026-10-27T00:29:06.557Z');

