-- project (6 rows)
INSERT OR IGNORE INTO "project" ("id", "title", "description", "imageUrl", "tags", "githubUrl", "liveUrl", "featured", "order", "createdAt") VALUES ('cmvpx7u41000dy01ni9xlj8ji', 'Nebula — AI Financial Telemetry Platform', 'A real-time analytics command center processing 2.4M+ daily events with sub-50ms WebSocket streams, hardware-accelerated canvas charts, role-based access control, and automated anomaly detection.', '/images/project-nova.svg', 'Next.js, TypeScript, WebSockets, SQLite WAL', 'https://github.com/ss04pp1-dotcom/Home-desing', '#projects', 1, 1, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "project" ("id", "title", "description", "imageUrl", "tags", "githubUrl", "liveUrl", "featured", "order", "createdAt") VALUES ('cmvpx7u41000ey01ns00u0lhp', 'Lumen — 3D Architectural Lighting Studio', 'An interactive industrial design showcase and real-time 3D wireframe configurator for bespoke architectural lighting. Achieved a 99 Lighthouse performance score with custom shader pipelines.', '/images/project-lumen.svg', 'React, WebGL, Framer Motion, Tailwind CSS', 'https://github.com/ss04pp1-dotcom/Home-desing', '#projects', 1, 2, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "project" ("id", "title", "description", "imageUrl", "tags", "githubUrl", "liveUrl", "featured", "order", "createdAt") VALUES ('cmvpx7u41000fy01nyxbswoxw', 'Pulse — Realtime Collaborative Workspace', 'Low-latency team communication platform featuring voice waveform rooms, threaded code discussions, optimistic UI updates, and offline-first local database synchronization.', '/images/project-pulse.svg', 'Next.js, WebSockets, Redis, TypeScript', 'https://github.com/ss04pp1-dotcom/Home-desing', '#projects', 0, 3, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "project" ("id", "title", "description", "imageUrl", "tags", "githubUrl", "liveUrl", "featured", "order", "createdAt") VALUES ('cmvpx7u41000gy01njfxe0se3', 'Atlas — Offline-First Field Telemetry PWA', 'An offline-capable progressive web application for distributed engineering teams. Synchronizes geospatial logs, media attachments, and diagnostic reports automatically upon reconnection.', '/images/project-nova.svg', 'PWA, IndexedDB, TypeScript, Next.js', 'https://github.com/ss04pp1-dotcom/Home-desing', '#projects', 0, 4, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "project" ("id", "title", "description", "imageUrl", "tags", "githubUrl", "liveUrl", "featured", "order", "createdAt") VALUES ('cmvpx7u42000hy01nqxolehrb', 'Forge — Headless Design System & Storefront', 'A zero-runtime-overhead storefront architecture with server-rendered product configurators, instant slide-over cart state, and full Schema.org rich snippet automation.', '/images/project-lumen.svg', 'Next.js, Stripe, Tailwind CSS, TypeScript', 'https://github.com/ss04pp1-dotcom/Home-desing', '#projects', 0, 5, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "project" ("id", "title", "description", "imageUrl", "tags", "githubUrl", "liveUrl", "featured", "order", "createdAt") VALUES ('cmvpx7u42000iy01n6j6jtt7c', 'Echo — Technical Documentation Studio', 'A distraction-free collaborative markdown and architecture diagramming workspace with real-time version diffs, keyboard-first command palette, and instant static export.', '/images/project-pulse.svg', 'React, TypeScript, Tailwind CSS, Framer Motion', 'https://github.com/ss04pp1-dotcom/Home-desing', '#projects', 0, 6, '2026-10-27T00:24:04.000Z');

-- experience (3 rows)
INSERT OR IGNORE INTO "experience" ("id", "role", "company", "period", "description", "current", "order", "createdAt") VALUES ('cmvpx7u43000jy01n6zlgk738', 'Senior Full-Stack Engineer', 'Stellar Labs', '2023 — Present', 'Leading the frontend and edge API architecture of a multi-tenant SaaS platform. Shipped a unified design system across 4 products, cut JS bundle size by 58%, and mentored a team of five engineers.', 1, 1, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "experience" ("id", "role", "company", "period", "description", "current", "order", "createdAt") VALUES ('cmvpx7u43000ky01n5lzl7mz5', 'Frontend & Interaction Engineer', 'PixelForge Studio', '2021 — 2023', 'Architected 15+ high-converting web applications and interactive product launches for international clients. Owned performance budgets, accessibility compliance (WCAG AA), and motion choreography.', 0, 2, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "experience" ("id", "role", "company", "period", "description", "current", "order", "createdAt") VALUES ('cmvpx7u43000ly01n5j25wtvr', 'Full-Stack Web Developer', 'CodeCraft Agency', '2019 — 2021', 'Built responsive React and Node.js applications from database schema design to production deployment. Established automated CI/CD checks and Lighthouse performance gates.', 0, 3, '2026-10-27T00:24:04.000Z');

-- education (2 rows)
INSERT OR IGNORE INTO "education" ("id", "degree", "institution", "period", "description", "order", "createdAt") VALUES ('cmvpx7u44000my01npczdkk72', 'BSc in Computer Science & Engineering', 'University of Dhaka', '2015 — 2019', 'Graduated with distinction. Undergraduate thesis on perceptual frame-rate stability and GPU-composited web interfaces. Led the university programming club and organized two national hackathons.', 1, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "education" ("id", "degree", "institution", "period", "description", "order", "createdAt") VALUES ('cmvpx7u44000ny01nz0e5ms28', 'Diploma in Interactive Systems & Typography', 'Bangladesh Design Institute', '2014 — 2015', 'Intensive foundation in grid systems, editorial typography, and human-computer interaction — bridging rigorous software engineering with visual craft.', 2, '2026-10-27T00:24:04.000Z');

-- service (4 rows)
INSERT OR IGNORE INTO "service" ("id", "title", "description", "icon", "order", "createdAt") VALUES ('cmvpx7u45000oy01nnfwgqaft', 'Full-Stack Web Engineering', 'End-to-end architecture of fast, resilient web applications — from SSR Next.js frontends and type-safe APIs to optimized SQLite/PostgreSQL data layers.', 'Code2', 1, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "service" ("id", "title", "description", "icon", "order", "createdAt") VALUES ('cmvpx7u45000py01njxo5q893', 'UI Systems & Product Design', 'Accessible, high-contrast interfaces and scalable component libraries engineered with strict typographic hierarchy and zero visual clutter.', 'Palette', 2, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "service" ("id", "title", "description", "icon", "order", "createdAt") VALUES ('cmvpx7u45000qy01njt32hedb', '60fps Motion & Interactive Canvas', 'Hardware-accelerated scroll choreography, compositor-safe micro-interactions, and optimized 2D/WebGL canvas experiences that never drop frames.', 'Sparkles', 3, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "service" ("id", "title", "description", "icon", "order", "createdAt") VALUES ('cmvpx7u45000ry01nddbl1h4n', 'Performance & Technical SEO Audits', 'Deep-dive codebase optimization: eliminating client-side waterfalls, shrinking bundle bloat, configuring SSR structured data, and passing Core Web Vitals.', 'Rocket', 4, '2026-10-27T00:24:04.000Z');

-- testimonial (4 rows)
INSERT OR IGNORE INTO "testimonial" ("id", "name", "role", "company", "content", "avatarUrl", "rating", "order", "createdAt") VALUES ('cmvpx7u46000sy01nkcwr6ge2', 'Sarah Mitchell', 'VP of Product', 'Stellar Labs', 'Salahuddin is the rare engineer who thinks like both a systems architect and a principal designer. He refactored our analytics platform, cutting initial load time from 3.2s to 420ms while elevating the entire UI.', '/images/avatar.svg', 5, 1, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "testimonial" ("id", "name", "role", "company", "content", "avatarUrl", "rating", "order", "createdAt") VALUES ('cmvpx7u46000ty01nuj4tgzk3', 'James Okafor', 'Managing Partner', 'Lumen Industrial', 'Every studio promises high performance, but Salahuddin actually delivers it — obsessive attention to animation frame budgets, SSR data hydration, and clean code. Our configurator conversion rate jumped 64%.', '', 5, 2, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "testimonial" ("id", "name", "role", "company", "content", "avatarUrl", "rating", "order", "createdAt") VALUES ('cmvpx7u46000uy01n16wy1fxk', 'Nadia Chen', 'CTO', 'PulseChat', 'He took a complex real-time spec and turned it into an architecture our engineering team loved reviewing. Zero unnecessary dependencies, rock-solid SQLite & WebSocket state, and effortless UX.', '', 5, 3, '2026-10-27T00:24:04.000Z');
INSERT OR IGNORE INTO "testimonial" ("id", "name", "role", "company", "content", "avatarUrl", "rating", "order", "createdAt") VALUES ('cmvpx7u46000vy01nlipnv84h', 'Tomás Rivera', 'Head of Growth', 'Atlas Systems', 'Our organic traffic and user retention doubled after the technical overhaul. The site does not just look refined — it loads instantaneously on every device and converts visitors into leads.', '', 5, 4, '2026-10-27T00:24:04.000Z');

